// 编译: nvcc -arch=sm_80 print_ids.cu -o print_ids && ./print_ids
#include <cstdio>
#include <cuda_runtime.h>

__global__ void print_ids() {
    int lane   = threadIdx.x % 32;                          // warp 内 lane 号 0..31
    int warp   = threadIdx.x / 32;                          // block 内第几个 warp
    int global = blockIdx.x * blockDim.x + threadIdx.x;     // 全局线程号
    if (lane == 0) {                                        // 每个 warp 只打印一行
        printf("block %d, warp %d: 该 warp 的全局起始线程 = %d\n",
               blockIdx.x, warp, global);
    }
}

int main() {
    cudaDeviceProp prop;
    cudaGetDeviceProperties(&prop, 0);
    printf("%s: %d 个 SM, 每 SM 最多 %d 线程, warpSize = %d\n",
           prop.name, prop.multiProcessorCount,
           prop.maxThreadsPerMultiProcessor, prop.warpSize);
    // 2 个 block x 64 线程 = 4 个 warp, 但只有 2 个 lane-0 线程各打印一次
    print_ids<<<2, 64>>>();
    cudaDeviceSynchronize();
    return 0;
}

