// 编译: nvcc -arch=sm_80 l2_vs_hbm.cu -o l2_vs_hbm && ./l2_vs_hbm
// 同一段读代码, 小数组命中 L2, 大数组必须走 HBM, 带宽差数倍
#include <cstdio>
#include <cuda_runtime.h>

__global__ void read_only(const float* __restrict__ a, float* __restrict__ sink, size_t n) {
    float acc = 0.0f;
    for (size_t i = blockIdx.x * (size_t)blockDim.x + threadIdx.x; i < n;
         i += (size_t)gridDim.x * blockDim.x)
        acc += a[i];                       // grid-stride 累加
    if (acc == -1.0f) sink[0] = acc;       // 防止编译器把整个读循环优化掉
}

float bench(const float* a, float* sink, size_t n, int grid, int block, int iters) {
    cudaEvent_t s, e;
    cudaEventCreate(&s); cudaEventCreate(&e);
    read_only<<<grid, block>>>(a, sink, n);
    cudaDeviceSynchronize();
    cudaEventRecord(s);
    for (int r = 0; r < iters; ++r) read_only<<<grid, block>>>(a, sink, n);
    cudaEventRecord(e);
    cudaEventSynchronize(e);
    float ms = 0.0f;
    cudaEventElapsedTime(&ms, s, e);
    return (float)((double)n * sizeof(float) * iters / (ms / 1e3) / 1e9);
}

int main() {
    float* sink;
    cudaMalloc(&sink, sizeof(float));
    size_t small = (size_t)2 << 20;      // 2M float = 8MB, 装得进 L2
    size_t big   = (size_t)256 << 20;    // 256M float = 1GB, 必须走 HBM
    float *a_small, *a_big;
    cudaMalloc(&a_small, small * sizeof(float));
    cudaMalloc(&a_big, big * sizeof(float));
    cudaMemset(a_small, 0, small * sizeof(float));
    cudaMemset(a_big, 0, big * sizeof(float));
    printf("8MB  (命中 L2) : %7.1f GB/s\n", bench(a_small, sink, small, 1024, 256, 200));
    printf("1GB  (走 HBM)  : %7.1f GB/s\n", bench(a_big, sink, big, 4096, 256, 5));
    printf("参考: A100 L2 40MB / HBM 2039 GB/s; H100 L2 50MB / HBM 3350 GB/s\n");
    cudaFree(a_small); cudaFree(a_big); cudaFree(sink);
    return 0;
}

