// 编译: nvcc -arch=sm_80 vector_add.cu -o vector_add && ./vector_add
#include <cstdio>
#include <cstdlib>
#include <cuda_runtime.h>

__global__ void vector_add(const float* __restrict__ a, const float* __restrict__ b,
                           float* __restrict__ c, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;   // 全局线程号
    if (i < n) c[i] = a[i] + b[i];                   // 必须边界判断
}

int main() {
    const int n = 1 << 20;                           // 1M 个元素
    size_t bytes = (size_t)n * sizeof(float);
    float* h_a = (float*)malloc(bytes);
    float* h_b = (float*)malloc(bytes);
    float* h_c = (float*)malloc(bytes);
    for (int i = 0; i < n; ++i) { h_a[i] = 1.0f; h_b[i] = 2.0f; }

    float *d_a, *d_b, *d_c;
    cudaMalloc(&d_a, bytes);
    cudaMalloc(&d_b, bytes);
    cudaMalloc(&d_c, bytes);
    cudaMemcpy(d_a, h_a, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(d_b, h_b, bytes, cudaMemcpyHostToDevice);

    int block = 256;
    int grid = (n + block - 1) / block;              // 4096 个 block
    vector_add<<<grid, block>>>(d_a, d_b, d_c, n);

    cudaError_t err = cudaGetLastError();            // 抓启动期错误
    if (err != cudaSuccess) {
        printf("kernel 启动失败: %s\n", cudaGetErrorString(err));
        return 1;
    }
    cudaMemcpy(h_c, d_c, bytes, cudaMemcpyDeviceToHost);
    printf("c[0] = %.1f, c[%d] = %.1f (期望 3.0)\n", h_c[0], n - 1, h_c[n - 1]);

    cudaFree(d_a); cudaFree(d_b); cudaFree(d_c);
    free(h_a); free(h_b); free(h_c);
    return 0;
}

