// 编译: nvcc -arch=sm_80 indexing.cu -o indexing && ./indexing
#include <cstdio>
#include <cuda_runtime.h>

#define ROWS 4
#define COLS 8

// 二维索引: x 方向映射最内层(连续)维度, y 方向映射行
__global__ void mat_add(const float* __restrict__ A, const float* __restrict__ B,
                        float* __restrict__ C, int rows, int cols) {
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    if (row < rows && col < cols) {
        int idx = row * cols + col;              // 行主序线性化
        C[idx] = A[idx] + B[idx];
    }
}

// grid-stride: 线程数与数据规模解耦, 一个 kernel 处理任意长度
__global__ void add_one(float* __restrict__ x, int n) {
    for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < n;
         i += gridDim.x * blockDim.x)
        x[i] += 1.0f;
}

int main() {
    const int n = ROWS * COLS;
    size_t bytes = (size_t)n * sizeof(float);
    float h[ROWS * COLS];
    for (int i = 0; i < n; ++i) h[i] = 1.0f;
    float *A, *B, *C;
    cudaMalloc(&A, bytes); cudaMalloc(&B, bytes); cudaMalloc(&C, bytes);
    cudaMemcpy(A, h, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(B, h, bytes, cudaMemcpyHostToDevice);

    dim3 block(4, 2);                                 // 4 x 2 = 8 线程
    dim3 grid((COLS + block.x - 1) / block.x, (ROWS + block.y - 1) / block.y);
    mat_add<<<grid, block>>>(A, B, C, ROWS, COLS);
    cudaDeviceSynchronize();
    cudaMemcpy(h, C, bytes, cudaMemcpyDeviceToHost);
    printf("C[0][0] = %.1f, C[%d][%d] = %.1f (期望 2.0)\n", h[0], ROWS - 1, COLS - 1, h[n - 1]);

    add_one<<<2, 4>>>(C, n);                          // 只用 8 个线程处理 32 个元素
    cudaDeviceSynchronize();
    cudaMemcpy(h, C, bytes, cudaMemcpyDeviceToHost);
    printf("加一之后 C[0][0] = %.1f (期望 3.0)\n", h[0]);

    cudaFree(A); cudaFree(B); cudaFree(C);
    return 0;
}

