// 编译: nvcc -arch=sm_80 coalescing.cu -o coalescing && ./coalescing
#include <cstdio>
#include <cuda_runtime.h>

#define N ((size_t)1 << 24)   // 16M 个 float = 64MB

// 合并访问: 线程 t 访问 a[base + t], 32 个线程的 4 字节请求
// 恰好落在同一个 128 字节 cache line 里 -> 1 次事务
__global__ void coalesced(const float* __restrict__ a, float* __restrict__ out) {
    size_t i = blockIdx.x * (size_t)blockDim.x + threadIdx.x;
    out[i] = a[i] + 1.0f;
}

// 跨步访问: 相邻线程地址相差 32 个 float = 128 字节,
// 每个线程独占一条 cache line, 只用 4/128 的有效数据 -> 32 次事务
__global__ void strided(const float* __restrict__ a, float* __restrict__ out) {
    size_t i = blockIdx.x * (size_t)blockDim.x + threadIdx.x;
    size_t j = (i * 32) % N;
    out[j] = a[j] + 1.0f;
}

typedef void (*KernelFn)(const float*, float*);

float bench(KernelFn k, const float* a, float* out, int grid, int block) {
    cudaEvent_t s, e;
    cudaEventCreate(&s); cudaEventCreate(&e);
    k<<<grid, block>>>(a, out);                    // 预热
    cudaDeviceSynchronize();
    cudaEventRecord(s);
    for (int r = 0; r < 5; ++r) k<<<grid, block>>>(a, out);
    cudaEventRecord(e);
    cudaEventSynchronize(e);
    float ms = 0.0f;
    cudaEventElapsedTime(&ms, s, e);
    double bytes = 2.0 * (double)N * sizeof(float) * 5;   // 读 N 个 + 写 N 个
    return (float)(bytes / (ms / 1e3) / 1e9);
}

int main() {
    size_t bytes = N * sizeof(float);
    float *a, *out;
    cudaMalloc(&a, bytes);
    cudaMalloc(&out, bytes);
    cudaMemset(a, 0, bytes);
    int block = 256, grid = (int)(N / block);
    printf("合并访问: %7.1f GB/s\n", bench(coalesced, a, out, grid, block));
    printf("跨步访问: %7.1f GB/s\n", bench(strided, a, out, grid, block));
    printf("参考: A100 峰值约 2039 GB/s, H100 约 3350 GB/s\n");
    cudaFree(a); cudaFree(out);
    return 0;
}

