// 编译: nvcc -arch=sm_80 tiled_matmul.cu -o tiled && ./tiled
#include <cstdio>
#include <cstdlib>
#include <cuda_runtime.h>

#define TILE 16
#define N 1024

__global__ void tiled_matmul(const float* __restrict__ A, const float* __restrict__ B,
                             float* __restrict__ C) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];
    int tx = threadIdx.x, ty = threadIdx.y;
    int row = blockIdx.y * TILE + ty;
    int col = blockIdx.x * TILE + tx;
    float acc = 0.0f;
    for (int t = 0; t < N / TILE; ++t) {
        As[ty][tx] = A[row * N + t * TILE + tx];     // 行内连续 -> 合并访问
        Bs[ty][tx] = B[(t * TILE + ty) * N + col];   // 行内连续 -> 合并访问
        __syncthreads();                              // 等本块数据搬完
        #pragma unroll
        for (int k = 0; k < TILE; ++k)
            acc += As[ty][k] * Bs[k][tx];             // 从共享内存复用
        __syncthreads();                              // 等所有人算完再覆盖
    }
    C[row * N + col] = acc;
}

int main() {
    size_t bytes = (size_t)N * N * sizeof(float);
    float *A, *B, *C, *h;
    cudaMalloc(&A, bytes); cudaMalloc(&B, bytes); cudaMalloc(&C, bytes);
    h = (float*)malloc(bytes);
    for (int i = 0; i < N * N; ++i) h[i] = 1.0f;      // 全 1 矩阵, C 的每个元素应为 N
    cudaMemcpy(A, h, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(B, h, bytes, cudaMemcpyHostToDevice);

    dim3 block(TILE, TILE);
    dim3 grid(N / TILE, N / TILE);
    tiled_matmul<<<grid, block>>>(A, B, C);           // 预热
    cudaDeviceSynchronize();

    cudaEvent_t s, e;
    cudaEventCreate(&s); cudaEventCreate(&e);
    cudaEventRecord(s);
    for (int r = 0; r < 20; ++r) tiled_matmul<<<grid, block>>>(A, B, C);
    cudaEventRecord(e);
    cudaEventSynchronize(e);
    float ms = 0.0f;
    cudaEventElapsedTime(&ms, s, e);

    cudaMemcpy(h, C, sizeof(float), cudaMemcpyDeviceToHost);
    printf("C[0][0] = %.0f (期望 %d)\n", h[0], N);
    printf("tiled SGEMM: %.2f ms, %.1f GFLOPS (A100 FP32 峰值 19500 GFLOPS)\n",
           ms / 20, 2.0 * N * N * N * 20 / (ms / 1e3) / 1e9);
    cudaFree(A); cudaFree(B); cudaFree(C); free(h);
    return 0;
}

