// 编译: nvcc -arch=sm_80 sgemm_reg.cu -o sgemm_reg && ./sgemm_reg
// 每个线程算 4x4 个输出: 共享内存读取 8 次, FMA 16 次
#include <cstdio>
#include <cstdlib>
#include <cuda_runtime.h>

#define BM 64
#define BN 64
#define BK 16
#define TM 4
#define TN 4
#define N 1024

__global__ void sgemm_reg(const float* __restrict__ A, const float* __restrict__ B,
                          float* __restrict__ C) {
    __shared__ float As[BK][BM];        // 转置存放: 读 As[k][m] 无 bank conflict
    __shared__ float Bs[BK][BN];
    int tx = threadIdx.x, ty = threadIdx.y;      // block 为 (16,16) = 256 线程
    int tid = ty * 16 + tx;
    int row0 = blockIdx.y * BM, col0 = blockIdx.x * BN;
    float acc[TM][TN] = {0.0f};

    for (int k0 = 0; k0 < N; k0 += BK) {
        #pragma unroll
        for (int i = 0; i < 4; ++i) {            // 256 线程搬 64x16 = 1024 个元素
            int idx = tid + i * 256;
            int m = idx % BM, k = idx / BM;      // 相邻线程取相邻 m -> 合并访问
            As[k][m] = A[(row0 + m) * N + k0 + k];
            Bs[k][m] = B[(k0 + k) * N + col0 + m];
        }
        __syncthreads();
        #pragma unroll
        for (int k = 0; k < BK; ++k) {
            float regA[TM], regB[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i) regA[i] = As[k][ty * TM + i];
            #pragma unroll
            for (int j = 0; j < TN; ++j) regB[j] = Bs[k][tx * TN + j];
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                #pragma unroll
                for (int j = 0; j < TN; ++j) acc[i][j] += regA[i] * regB[j];
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j)
            C[(row0 + ty * TM + i) * N + col0 + tx * TN + j] = acc[i][j];
}

int main() {
    size_t bytes = (size_t)N * N * sizeof(float);
    float *A, *B, *C, *h;
    cudaMalloc(&A, bytes); cudaMalloc(&B, bytes); cudaMalloc(&C, bytes);
    h = (float*)malloc(bytes);
    for (int i = 0; i < N * N; ++i) h[i] = 1.0f;
    cudaMemcpy(A, h, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(B, h, bytes, cudaMemcpyHostToDevice);

    dim3 block(16, 16), grid(N / BN, N / BM);
    sgemm_reg<<<grid, block>>>(A, B, C);          // 预热
    cudaDeviceSynchronize();

    cudaEvent_t s, e;
    cudaEventCreate(&s); cudaEventCreate(&e);
    cudaEventRecord(s);
    for (int r = 0; r < 50; ++r) sgemm_reg<<<grid, block>>>(A, B, C);
    cudaEventRecord(e);
    cudaEventSynchronize(e);
    float ms = 0.0f;
    cudaEventElapsedTime(&ms, s, e);

    cudaMemcpy(h, C, sizeof(float), cudaMemcpyDeviceToHost);
    printf("C[0][0] = %.0f (期望 %d)\n", h[0], N);
    printf("register-tiled SGEMM: %.2f ms, %.1f GFLOPS\n",
           ms / 50, 2.0 * N * N * N * 50 / (ms / 1e3) / 1e9);
    printf("对比: A100 上 cuBLAS SGEMM 约 15000 GFLOPS, FP16 Tensor Core 峰值 312 TFLOPS\n");
    cudaFree(A); cudaFree(B); cudaFree(C); free(h);
    return 0;
}

