// 编译: nvcc -arch=sm_80 reduce.cu -o reduce && ./reduce
#include <cstdio>
#include <cstdlib>
#include <cuda_runtime.h>

__inline__ __device__ float warp_reduce_sum(float v) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1)
        v += __shfl_down_sync(0xffffffffu, v, offset);   // 5 步归约 32 个值
    return v;
}

__global__ void fill_ones(float* __restrict__ a, int n) {
    for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < n; i += gridDim.x * blockDim.x)
        a[i] = 1.0f;
}

__global__ void reduce_sum(const float* __restrict__ in, float* __restrict__ out, int n) {
    float sum = 0.0f;
    for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < n; i += gridDim.x * blockDim.x)
        sum += in[i];                                    // grid-stride 累加
    sum = warp_reduce_sum(sum);
    __shared__ float partial[32];                        // 每 block 最多 32 个 warp
    int lane = threadIdx.x % 32, wid = threadIdx.x / 32;
    if (lane == 0) partial[wid] = sum;
    __syncthreads();                                     // 等所有 warp 写完
    if (wid == 0) {
        sum = (threadIdx.x < blockDim.x / 32) ? partial[lane] : 0.0f;
        sum = warp_reduce_sum(sum);
        if (threadIdx.x == 0) out[blockIdx.x] = sum;     // 每个 block 一个部分和
    }
}

int main() {
    const int n = 1 << 24;                               // 16M 个 1.0f
    size_t bytes = (size_t)n * sizeof(float);
    float *d_in, *d_out;
    cudaMalloc(&d_in, bytes);
    int block = 256, grid = 512;                         // 512 个 block, 每 block 一个部分和
    cudaMalloc(&d_out, grid * sizeof(float));
    fill_ones<<<grid, block>>>(d_in, n);
    cudaDeviceSynchronize();

    cudaEvent_t s, e;
    cudaEventCreate(&s); cudaEventCreate(&e);
    cudaEventRecord(s);
    for (int r = 0; r < 20; ++r) reduce_sum<<<grid, block>>>(d_in, d_out, n);
    cudaEventRecord(e);
    cudaEventSynchronize(e);
    float ms = 0.0f;
    cudaEventElapsedTime(&ms, s, e);

    float* h = (float*)malloc(grid * sizeof(float));
    cudaMemcpy(h, d_out, grid * sizeof(float), cudaMemcpyDeviceToHost);
    double total = 0.0;
    for (int i = 0; i < grid; ++i) total += h[i];
    printf("sum = %.0f (期望 %d)\n", total, n);
    printf("有效带宽: %.1f GB/s (A100 峰值 2039 GB/s)\n",
           (double)n * sizeof(float) * 20 / (ms / 1e3) / 1e9);
    cudaFree(d_in); cudaFree(d_out); free(h);
    return 0;
}

