    cudaMalloc(&A, bytes);
    cudaMalloc(&B, bytes);
    cudaMalloc(&C, bytes);
    fill_one<<<1024, 256>>>(A, M * K);   // 全 1 矩阵, C 的每个元素应为 K
    fill_one<<<1024, 256>>>(B, K * N);
    cudaMemset(C, 0, bytes);

    cublasHandle_t handle;
    cublasCreate(&handle);
    float alpha = 1.0f, beta = 0.0f;
    // cuBLAS 是列主序: 计算 C^T = B^T A^T, 恰好等于行主序下的 C = A x B
    cublasSgemm(handle, CUBLAS_OP_N, CUBLAS_OP_N,
                N, M, K,           // 注意 m 与 n 交换
                &alpha, B, N,      // 第一个操作数传 B
                A, K,              // 第二个操作数传 A
                &beta, C, N);
    cudaDeviceSynchronize();

    float h = 0.0f;
    cudaMemcpy(&h, C, sizeof(float), cudaMemcpyDeviceToHost);
    printf("C[0][0] = %.1f (期望 %d)\n", h, K);

    cudaEvent_t s, e;
    cudaEventCreate(&s); cudaEventCreate(&e);
    cudaEventRecord(s);
    for (int r = 0; r < 20; ++r)
        cublasSgemm(handle, CUBLAS_OP_N, CUBLAS_OP_N, N, M, K,
                    &alpha, B, N, A, K, &beta, C, N);
    cudaEventRecord(e);
    cudaEventSynchronize(e);
    float ms = 0.0f;
    cudaEventElapsedTime(&ms, s, e);
    printf("cuBLAS SGEMM: %.2f ms, %.1f TFLOPS (A100 FP32 峰值 19.5 TFLOPS)\n",
           ms / 20, 2.0 * M * N * K * 20 / (ms / 1e3) / 1e12);

