// 编译: nvcc -arch=sm_80 flash_attn_simple.cu -o fa && ./fa
// 简化版 FlashAttention 前向: 每个线程负责一行 query, 分块遍历 K/V,
// 用在线 softmax 增量更新, 全程不物化 N*N 的分数矩阵
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <cuda_runtime.h>

#define D 64      // head dim
#define BC 64     // K/V 的列块大小

__global__ void flash_attn_fwd(const float* __restrict__ Q, const float* __restrict__ K,
                               const float* __restrict__ V, float* __restrict__ O,
                               int N, float scale) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= N) return;
    const float* q = Q + (size_t)row * D;
    float acc[D];
    float m = -INFINITY, l = 0.0f;                 // running max / running sum
    for (int d = 0; d < D; ++d) acc[d] = 0.0f;

    for (int j0 = 0; j0 < N; j0 += BC) {
        int jend = min(j0 + BC, N);
        float m_blk = -INFINITY;                   // 第一遍: 本块的 max
        for (int j = j0; j < jend; ++j) {
            const float* k = K + (size_t)j * D;
            float s = 0.0f;
            for (int d = 0; d < D; ++d) s += q[d] * k[d];
            m_blk = fmaxf(m_blk, s * scale);
        }
        float m_new = fmaxf(m, m_blk);
        float alpha = __expf(m - m_new);           // 旧累加器的缩放系数
        for (int d = 0; d < D; ++d) acc[d] *= alpha;
        l *= alpha;
        for (int j = j0; j < jend; ++j) {          // 第二遍: 累加 P @ V
            const float* k = K + (size_t)j * D;
            float s = 0.0f;
            for (int d = 0; d < D; ++d) s += q[d] * k[d];
            float p = __expf(s * scale - m_new);
            const float* v = V + (size_t)j * D;
            for (int d = 0; d < D; ++d) acc[d] += p * v[d];
            l += p;
        }
        m = m_new;
    }
    float* o = O + (size_t)row * D;
    for (int d = 0; d < D; ++d) o[d] = acc[d] / l;  // 最后统一归一化
}

int main() {
    const int N = 1024;
    size_t bytes = (size_t)N * D * sizeof(float);
    float *Q, *K, *V, *O, *h;
    cudaMalloc(&Q, bytes); cudaMalloc(&K, bytes);
    cudaMalloc(&V, bytes); cudaMalloc(&O, bytes);
    h = (float*)malloc(bytes);
    for (size_t i = 0; i < (size_t)N * D; ++i) h[i] = 0.01f * (float)(i % 17);
    cudaMemcpy(Q, h, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(K, h, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(V, h, bytes, cudaMemcpyHostToDevice);

    int block = 256, grid = (N + block - 1) / block;
    flash_attn_fwd<<<grid, block>>>(Q, K, V, O, N, 1.0f / sqrtf((float)D));
    cudaDeviceSynchronize();

    cudaMemcpy(h, O, 3 * sizeof(float), cudaMemcpyDeviceToHost);
    printf("O[0][0..2] = %.5f %.5f %.5f\n", h[0], h[1], h[2]);
    printf("标准 attention 的中间矩阵 %.1f MB -> FlashAttention 只保留 O(N*D) = %.2f MB\n",
           (double)N * N * 4 / 1e6, (double)N * D * 4 / 1e6);
    cudaFree(Q); cudaFree(K); cudaFree(V); cudaFree(O); free(h);
    return 0;
}

